command:
// ==========================================
// 🌙 LUNAS WECKER (V01.02 Ready - Universeller & dynamischer Bibliothekar)
// ==========================================
(async () => {
    // --- 1. FRAMEWORK WECKEN ---
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) await fwMacro.execute();
    await new Promise(resolve => setTimeout(resolve, 150));

    const DSK_FW = globalThis.DSK || DSK;
    if (!DSK_FW || !DSK_FW.EffektEnde) return ui.notifications.error("Luna sagt 🌙: Framework fehlerhaft!");

    // --- 2. KOMPENDIUM LADEN ---
    const pack = game.packs.get("dsk-havena-und-umland.makros");
    if (!pack) return ui.notifications.error("Luna sagt 🌙: Kompendium nicht gefunden!");
    const alleMakros = await pack.getDocuments();

    const gefundeneEffekte = new Set();
    const reaktivierteGaben = new Set();

    // --- 3. HILFSFUNKTION: BLOCK-18-ANGRIFFSWÄCHTER REAKTIVIEREN ---
    const reaktiviereAngriffswaechter = (actor, effect) => {
        if (!DSK_FW?.Schaden?.Angriffswaechter?.Register) return false;
        const reaktionsKey = effect.getFlag("dsk", "schadensReaktion");
        if (!reaktionsKey) return false;

        // A) FUNKENFELL (Verteidiger-Vergeltung)
        if (effect.getFlag("dsk", "isFunkenfell")) {
            DSK_FW.Schaden.Angriffswaechter.Register({
                key: `${reaktionsKey}-${actor.uuid}`,
                actor,
                effektId: effect.id,
                effektUuid: effect.uuid,
                rolle: "verteidiger",
                einmalig: false,
                protokollieren: true,
                beiErfolg: async ({ actor, effekt, message, angriff }) => {
                    if (!DSK_FW.Schaden.IstAktiverGM() || !actor || !effekt || !message || !angriff || angriff.schaden <= 0) return false;
                    const zielDaten = DSK_FW.Schaden.FindeActor(angriff.angreiferName, actor.id);
                    if (!zielDaten?.actor) return false;
                    const zielActor = zielDaten.actor;
                    if (zielActor.id === actor.id || zielActor.uuid === actor.uuid) return false;

                    const zielName = zielDaten.token?.name || zielDaten.name || DSK_FW.ResolveTokenName(zielActor);
                    const effekttraegerName = DSK_FW.ResolveTokenName(actor);
                    const basisTP = Math.max(1, Math.floor(Number(effekt.getFlag("dsk", "vergeltungsSchaden")) || 1));
                    const ahne = effekt.getFlag("dsk", "ahne") || "Rondra";

                    const schadensKarte = await DSK_FW.Schaden.GMKarte({
                        key: `${reaktionsKey}-${effekt.id}-${message.id}`,
                        titel: "Funkenfell – Vergeltung",
                        ahne,
                        zusammenfassung: `Angreifer erkannt: ${zielName}`,
                        beschreibung: `<b>${zielName}</b> gewinnt gegen <b>${effekttraegerName}</b>. Das Funkenfell schlägt gegen den Angreifer zurück.<br><br>Der Angreifer erleidet <b>${basisTP} TP</b> Vergeltungsschaden.`,
                        modus: "fest",
                        basis: basisTP,
                        ziele: [{ uuid: zielActor.uuid, name: zielName }],
                        buttonText: `${basisTP} TP anwenden`,
                        bestaetigungsTitel: "Funkenfell – Schaden angewendet",
                        quelleUuid: actor.uuid,
                        effektUuid: effekt.uuid,
                        effektVerbrauchen: false,
                        lepDetailsVerbergen: true
                    });
                    return Boolean(schadensKarte);
                }
            });
            return true;
        }

        // B) BLITZSCHLAG & WAFFEN-ENTLADUNGEN (Angreifer-Bonus)
        if (effect.getFlag("dsk", "isBlitzschlag") || effect.getFlag("dsk", "rolle") === "angreifer") {
            const erlaubteWaffen = effect.getFlag("dsk", "erlaubteWaffen") || [];
            const klingenName = effect.getFlag("dsk", "klingenName") || erlaubteWaffen[0];
            if (!klingenName) return false;

            DSK_FW.Schaden.Angriffswaechter.Register({
                key: `${reaktionsKey}-${actor.uuid}`,
                actor,
                effektId: effect.id,
                effektUuid: effect.uuid,
                erlaubteWaffen: [klingenName],
                rolle: "angreifer",
                einmalig: Boolean(effect.getFlag("dsk", "einmalig") ?? true),
                protokollieren: true,
                beiErfolg: async ({ actor, effekt, message, angriff, waffenName }) => {
                    if (!DSK_FW.Schaden.IstAktiverGM() || !actor || !effekt || !message || !angriff || angriff.schaden <= 0) return false;
                    const gespeicherteKlinge = String(effekt.getFlag("dsk", "klingenName") || klingenName);
                    if (!DSK_FW.Schaden.Angriffswaechter._WaffePasst(waffenName, [gespeicherteKlinge])) return false;

                    const zielDaten = DSK_FW.Schaden.FindeActor(angriff.verteidigerName, actor.id);
                    if (!zielDaten?.actor) return false;
                    const zielActor = zielDaten.actor;
                    if (zielActor.id === actor.id || zielActor.uuid === actor.uuid) return false;

                    const zielName = zielDaten.token?.name || zielDaten.name || DSK_FW.ResolveTokenName(zielActor);
                    const casterName = DSK_FW.ResolveTokenName(actor);
                    const basisTP = Math.max(0, Math.floor(Number(angriff.schaden) || 0));
                    const bonusTP = Math.max(1, Math.floor(Number(effekt.getFlag("dsk", "bonus")) || 1));
                    if (basisTP <= 0) return false;

                    const schadensKarte = await DSK_FW.Schaden.GMKarte({
                        key: `${reaktionsKey}-${effekt.id}-${message.id}`,
                        titel: "Blitzschlag – Entladung",
                        ahne: "Rondra",
                        zusammenfassung: `Getroffen: ${zielName}`,
                        beschreibung: `<b>${casterName}</b> hat <b>${zielName}</b> erfolgreich mit <b>${waffenName}</b> angegriffen.<br><br>Die aufgeladene Meisterklinge entlädt Rondras Zorn. Der erkannte Schaden wird um <b>+${bonusTP} TP</b> erhöht.`,
                        modus: "addition",
                        basis: basisTP,
                        bonus: bonusTP,
                        ziele: [{ uuid: zielActor.uuid, name: zielName }],
                        buttonText: "Gesamtschaden anwenden",
                        bestaetigungsTitel: "Blitzschlag – Schaden angewendet",
                        effektUuid: effekt.uuid,
                        effektVerbrauchen: true,
                        quelleUuid: actor.uuid,
                        abschlussText: "...und Rondras Segen endet.",
                        vollTrefferText: "...und Rondras Segen endet.",
                        lepDetailsVerbergen: true
                    });
                    return Boolean(schadensKarte);
                }
            });
            return true;
        }

        return false;
    };

    // --- 4. ALLE AKTEURE SCANNEN ---
    const alleAkteure = new Set();
    if (canvas.scene) canvas.scene.tokens.forEach(t => { if (t.actor) alleAkteure.add(t.actor); });
    game.actors.forEach(a => alleAkteure.add(a));

    let verborgenerWurfAktiv = false;

    for (let actor of alleAkteure) {
        for (let effect of actor.effects) {
            if (effect.disabled) continue;
            const eName = effect.name || effect.label || "";
            if (!eName.includes("(")) continue;

            // Stumme Partner direkt abfangen
            if (effect.getFlag("dsk", "stummerPartner")) {
                reaktivierteGaben.add(eName + " <span style='font-size: 0.85em; opacity: 0.7;'>(Stiller Partner)</span>");
                continue;
            }

            const basisName = eName.split("(")[0].trim();

            // A) WIRKUNGSENDE AUS V01.02-FLAGS DIREKT WIEDERHERSTELLEN
            const endeFlag = effect.getFlag("dsk", "wirkungsende");
            const ahnenId = effect.getFlag("dsk", "ahnenId");
            let wurdeRegistriert = false;

            if (endeFlag?.sfName && endeFlag?.beschreibungFuerEnde) {
                DSK_FW.EffektEnde.Register(
                    endeFlag.sfName,
                    endeFlag.basisEffektName || eName,
                    endeFlag.beschreibungFuerEnde
                );
                wurdeRegistriert = true;
            }

            // B) ANGRIFFSWÄCHTER (Block 18) REAKTIVIEREN
            if (effect.getFlag("dsk", "schadensReaktion")) {
                reaktiviereAngriffswaechter(actor, effect);
            }

            // C) VERBORGENER WURF MERKEN
            if (effect.getFlag("dsk", "isVerborgenerWurf")) {
                verborgenerWurfAktiv = true;
            }

            // D) MAKRO IM KOMPENDIUM SUCHEN (auch über Such-Normalisierung)
            const macro = alleMakros.find(m =>
                m.name.toLowerCase().trim() === basisName.toLowerCase().trim() ||
                basisName.toLowerCase().startsWith(m.name.toLowerCase().trim())
            );

            if (macro) {
                gefundeneEffekte.add(effect.id);
                reaktivierteGaben.add(eName);

                const codeText = macro.command || "";

                // Spezial-Gaben mit eigenem WeckerAufruf / initMode ausführen
                if (codeText.includes("initMode") || codeText.includes("WeckerAufruf")) {
                    try {
                        await macro.execute("WeckerAufruf");
                    } catch (e) {
                        console.error(`Luna sagt 🌙: Fehler beim Laden des Init-Modus für ${basisName}`, e);
                    }
                }

                // Fallback für ältere Makros ohne v01.02-wirkungsende-Flag
                if (!wurdeRegistriert) {
                    const regMatch = codeText.match(/EffektEnde\.Register\s*\(\s*[^,]+,\s*[^,]+,\s*(["'`])(.*?)\1\s*\)/);
                    const varMatch = codeText.match(/(?:endeText|abschlussText)\s*=\s*(["'`])([\s\S]*?)\1/);
                    const beschreibung = regMatch ? regMatch[2] : (varMatch ? varMatch[2] : `Die Kraft von ${eName} verblasst.`);

                    if (ahnenId) {
                        DSK_FW.EffektEnde.Register(ahnenId, eName.split("-")[0].trim(), beschreibung);
                    }
                    DSK_FW.EffektEnde.Register(effect.id, eName, beschreibung);
                }
            } else if (wurdeRegistriert) {
                gefundeneEffekte.add(effect.id);
                reaktivierteGaben.add(eName);
            }
        }
    }

    // --- 5. UNIVERSELLE SICHERHEITSNETZE & WÄCHTER (Immer aktiv!) ---
    if (verborgenerWurfAktiv) {
        if (globalThis._dskVerborgenerWurfHookId) {
            Hooks.off("createChatMessage", globalThis._dskVerborgenerWurfHookId);
        }
        globalThis._dskVerborgenerWurfHookId = Hooks.on("createChatMessage", async message => {
            const aktiverGM = game.users.find(u => u.isGM && u.active);
            const darfSenden = aktiverGM ? (game.user.isGM && game.user.id === aktiverGM.id) : game.user.isGM;
            if (!darfSenden || !message) return;
            if (message.speaker?.alias === "System" || message.flags?.dsk?.isWatcherMsg) return;

            const rawContent = [String(message.flavor || ""), String(message.content || "")].join(" ");
            const cleanText = rawContent.replace(/<[^>]*>?/gm, " ").replace(/\s+/g, " ").trim().toLowerCase();
            if (!cleanText.includes("sinnessch")) return;

            let hoechsteQS = 0;
            const verborgeneNamen = [];

            for (const token of canvas.tokens?.placeables || []) {
                const act = token?.actor;
                if (!act) continue;
                const eff = (act.effects || []).find(e => !e.disabled && e.getFlag("dsk", "isVerborgenerWurf") === true);
                if (!eff) continue;
                const qsVal = Math.max(1, Number(eff.getFlag("dsk", "qs")) || 1);
                if (qsVal > hoechsteQS) hoechsteQS = qsVal;
                verborgeneNamen.push(token.name || act.name);
            }

            if (!verborgeneNamen.length) return;
            const erschwernis = hoechsteQS * 2;
            const suchender = message.speaker?.alias || "Ein Suchender";

            const whisperHtml = `
                <div style="font-family:'Signika',sans-serif;">
                    ${DSK_FW.UI.Header("Verborgener Wurf (Rondra)", DSK_FW.Symbol("Rondra"))}
                    <div class="dskbox2" style="margin-top:10px;color:#000;font-size:0.95em;">
                        <p style="margin-bottom:8px;"><b>${suchender}</b> hat eine Sinnesschärfe-Probe abgelegt.</p>
                        <hr style="margin:8px 0;border:0;border-top:1px solid #c9bca6;">
                        <p style="margin-bottom:8px;">Wenn du versuchst, jemanden wahrzunehmen, greift der Effekt <b>Verborgener Wurf</b>.</p>
                        <p style="margin-bottom:4px;font-weight:bold;color:#76301b;">Vorgehen:</p>
                        <ul class="dsklist" style="margin-top:0;margin-bottom:0;">
                            <li>Ziehe <b>${erschwernis}</b> von deinem Probenwert ab.</li>
                            <li>Vergleiche den Wurf mit dem neuen Wert.</li>
                            <li><b style="color:#18940F;">Erfolg:</b> Habe bitte einen Moment Geduld, die Spielleitung beschreibt dir gleich, was du entdeckst.</li>
                            <li><b style="color:#B30000;">Misserfolg:</b> Du nimmst nichts wahr.</li>
                        </ul>
                    </div>
                </div>
            `;

            const whisperIds = new Set(DSK_FW.Empfaenger.GM());
            const authorId = message.author?.id || message.user?.id;
            if (authorId) whisperIds.add(authorId);

            await ChatMessage.create({
                whisper: Array.from(whisperIds).filter(id => game.users.get(id)),
                content: whisperHtml,
                speaker: { alias: "System" },
                flags: { dsk: { isWatcherMsg: true } }
            });
        });
    }

    if (!globalThis._lunasSicherheitsNetz) {
        globalThis._lunasSicherheitsNetz = true;

        // 🧹 1. UNIVERSELLER ITEM-STAUBSAUGER
        Hooks.on("preDeleteActiveEffect", async (eff) => {
            if (!game.user.isGM || !eff.parent) return;
            const effName = eff.name || eff.label || "";
            if (effName.includes("(")) {
                const linkedItem = eff.parent.items.find(i => i.name === effName);
                if (linkedItem) await linkedItem.delete();
            }
        });

        // 🔴 2. ROTER SCHIMMER: WILLENSKRAFT-WÄCHTER
        Hooks.on("createChatMessage", async (msg) => {
            if (msg.user.id !== game.user.id) return;
            const content = (msg.content || "").toLowerCase();
            const flavor = (msg.flavor || "").toLowerCase();

            if (content.includes("willenskraft") || flavor.includes("willenskraft")) {
                const speaker = msg.speaker;
                let rollActor = game.actors.get(speaker.actor);
                if (!rollActor && speaker.token) rollActor = canvas.scene.tokens.get(speaker.token)?.actor;
                if (!rollActor) return;

                const hatJagdfieberEffekt = rollActor.effects.some(e => {
                    const n = (e.name || e.label || "").toLowerCase();
                    return n.includes("roter schimmer") && n.includes("jagdfieber");
                });

                if (hatJagdfieberEffekt) {
                    const hatJagdfieberEigenschaft = rollActor.items.some(i => (i.name || "").toLowerCase().includes("jagdfieber"));
                    if (hatJagdfieberEigenschaft) {
                        const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);
                        let whisperTargets = [...new Set([...game.users.filter(u => u.isGM).map(u => u.id), ...getOwners(rollActor)])].filter(id => game.users.get(id));
                        await ChatMessage.create({
                            whisper: whisperTargets, speaker: { alias: "System" },
                            content: `
                                <div style="font-family: 'Signika', sans-serif;">
                                    <div class="dskbox1">
                                        <p style="font-weight:bold; margin-top:6px; margin-bottom:0;">Jagdfieber blockiert Probe!</p>
                                    </div>
                                    <div class="dskbox2" style="margin-top:10px; text-align: center;">
                                        <p style="color:#000; font-weight:bold; font-size:1.1em;">${rollActor.name}</p>
                                        <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                                        <p style="margin-bottom: 8px;">Da das Ziel unter dem Einfluss des <b>Roten Schimmers</b> steht und die Eigenschaft <b>Jagdfieber</b> besitzt, wird der Instinkt übermächtig!</p>
                                        <p style="color:#8b0000; font-weight:bold;">Die Probe darf nicht abgelegt werden und gilt als automatisch gescheitert.</p>
                                    </div>
                                </div>
                            `
                        });
                    }
                }
            }
        });

        // 🦇 3. UNIVERSAL-SYNC (FLEDERMAUS & ÄHNLICHE TIERE)
        Hooks.on("updateActor", async (updatedActor, changes, options) => {
            if (!game.user.isGM || options.dskUniversalSync) return;
            const lepChange = foundry.utils.getProperty(changes, "system.stats.LeP.value");
            const aepChange = foundry.utils.getProperty(changes, "system.stats.AeP.value");
            if (lepChange === undefined && aepChange === undefined) return;

            if (updatedActor.isToken) {
                const casterUuid = updatedActor.token.getFlag("dsk", "isFledermausVon");
                if (casterUuid) {
                    const casterAct = await fromUuid(casterUuid);
                    if (casterAct) {
                        let finalUpdate = {};
                        if (lepChange !== undefined) {
                            const batMax = updatedActor.system.stats.LeP.max || 1;
                            const pct = Math.max(0, Math.min(1, lepChange / batMax));
                            finalUpdate["system.stats.LeP.value"] = Math.round((casterAct.system.stats.LeP.max || 1) * pct);
                        }
                        if (aepChange !== undefined) {
                            const batMax = updatedActor.system.stats.AeP.max || 1;
                            const pct = Math.max(0, Math.min(1, aepChange / batMax));
                            finalUpdate["system.stats.AeP.value"] = Math.round((casterAct.system.stats.AeP.max || 1) * pct);
                        }
                        if (Object.keys(finalUpdate).length > 0) await casterAct.update(finalUpdate, { dskUniversalSync: true });
                    }
                }
            } else {
                const bats = canvas.scene ? canvas.scene.tokens.filter(t => t.getFlag("dsk", "isFledermausVon") === updatedActor.uuid) : [];
                for (let bat of bats) {
                    if (bat.actor) {
                        let finalUpdate = {};
                        if (lepChange !== undefined) {
                            const casterMax = updatedActor.system.stats.LeP.max || 1;
                            const pct = Math.max(0, Math.min(1, lepChange / casterMax));
                            finalUpdate["system.stats.LeP.value"] = Math.max(1, Math.round((bat.actor.system.stats.LeP.max || 1) * pct));
                        }
                        if (aepChange !== undefined) {
                            const casterMax = updatedActor.system.stats.AeP.max || 1;
                            const pct = Math.max(0, Math.min(1, aepChange / casterMax));
                            finalUpdate["system.stats.AeP.value"] = Math.round((bat.actor.system.stats.AeP.max || 1) * pct);
                        }
                        if (Object.keys(finalUpdate).length > 0) await bat.actor.update(finalUpdate, { dskUniversalSync: true });
                    }
                }
            }
        });

        // 🗑️ 4. ZENTRALER LÖSCH-WÄCHTER
        Hooks.on("deleteActiveEffect", async (eff) => {
            if (!game.user.isGM) return;

            const tId = eff.getFlag("dsk", "templateId");
            if (tId && canvas.scene) {
                const doc = canvas.scene.templates.get(tId);
                if (doc) await doc.delete();
            }

            const summonedActorId = eff.getFlag("dsk", "summonedActorId");
            if (summonedActorId) {
                const sActor = game.actors.get(summonedActorId);
                if (sActor) await sActor.delete();
            }

            const actorUuid = eff.parent?.uuid;
            if (actorUuid && canvas.scene) {
                const spawnedTokens = canvas.scene.tokens.filter(t => t.getFlag("dsk", "isMausVon") === actorUuid || t.getFlag("dsk", "isFledermausVon") === actorUuid);

                if (spawnedTokens.length > 0) {
                    const spawnedActor = spawnedTokens[0].actor;
                    if (spawnedActor && eff.parent) {
                        let finalUpdate = {};
                        const sLeVal = spawnedActor.system.stats.LeP.value;
                        if (sLeVal !== undefined) {
                            const sMax = spawnedActor.system.stats.LeP.max || 1;
                            const pct = Math.max(0, Math.min(1, sLeVal / sMax));
                            finalUpdate["system.stats.LeP.value"] = Math.round((eff.parent.system.stats.LeP.max || 1) * pct);
                        }
                        const sAeVal = spawnedActor.system.stats.AeP?.value;
                        if (sAeVal !== undefined) {
                            const sMax = spawnedActor.system.stats.AeP?.max || 1;
                            const pct = Math.max(0, Math.min(1, sAeVal / sMax));
                            finalUpdate["system.stats.AeP.value"] = Math.round((eff.parent.system.stats.AeP.max || 1) * pct);
                        }
                        if (Object.keys(finalUpdate).length > 0) await eff.parent.update(finalUpdate, { dskUniversalSync: true });
                    }
                }

                const hiddenTokenUuid = eff.getFlag("dsk", "hiddenTokenUuid");
                if (hiddenTokenUuid) {
                    const origTokenDoc = await fromUuid(hiddenTokenUuid);
                    if (origTokenDoc) await origTokenDoc.update({ hidden: false });
                } else {
                    const hiddenId = eff.getFlag("dsk", "hiddenTokenId");
                    if (hiddenId) {
                        const origToken = canvas.scene.tokens.get(hiddenId);
                        if (origToken) await origToken.update({ hidden: false });
                    }
                }

                if (spawnedTokens.length > 0) {
                    await canvas.scene.deleteEmbeddedDocuments("Token", spawnedTokens.map(t => t.id));
                }
            }
        });
    }

    // --- 6. CHAT-AUSGABE BAUEN ---
    let statusText = "";
    if (reaktivierteGaben.size > 0) {
        const effekteListe = Array.from(reaktivierteGaben).map(e => `<li style="margin-bottom:4px;"><b>${e}</b></li>`).join("");
        statusText = `
            <p style="color: #18940F; font-weight: bold; margin-bottom: 8px; text-align: left;">Scanner erfolgreich!</p>
            <p style="margin-bottom: 6px; text-align: left;">Der Wecker hat das Kompendium und die V01.02-Effektdaten gelesen und folgende aktive Gaben reaktiviert:</p>
            <ul class="dsklist" style="margin-top: 0; margin-bottom: 0; text-align: left;">
                ${effekteListe}
            </ul>
        `;
    } else {
        statusText = `
            <p style="color: #76301b; font-weight: bold; margin-bottom: 8px; text-align: left;">Scanner abgeschlossen.</p>
            <p style="margin-bottom: 0; text-align: left;">Es wurden aktuell keine aktiven Gaben auf den Akteuren gefunden. Alle globalen Sicherheitsnetze sind bereit.</p>
        `;
    }

    const contentHTML = `
        <div style="font-family: 'Signika', sans-serif;">
            <div class="dskbox1">
                <p style="display:flex; gap:8px; align-items:center; margin:0;">
                    <span style="font-size: 24px;">🌙</span>
                    <b>System Online</b>
                </p>
                <p style="font-weight:bold; margin-top:6px; margin-bottom:0;">Lunas Wecker</p>
            </div>
            <div class="dskbox2" style="margin-top:10px;">
                <p style="margin-bottom: 8px; text-align: left;">Guten Morgen! Die Welt ist erwacht.</p>
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                ${statusText}
            </div>
        </div>
    `;

    await ChatMessage.create({
        speaker: { alias: "System" },
        whisper: game.users.filter(u => u.isGM).map(u => u.id),
        content: contentHTML
    });
})();
